def get_status(expiry_date):
    if not expiry_date:
        return ""

    days_left = frappe.utils.date_diff(
        frappe.utils.getdate(expiry_date),
        frappe.utils.getdate(frappe.utils.nowdate())
    )

    if days_left > 60:
        return "Valid"
    elif days_left > 30:
        return "Expiring Soon"
    elif days_left >= 0:
        return "Expiring"
    else:
        return "Expired"

def worst_status(statuses):
    for s in ["Expired", "Expiring", "Expiring Soon", "Valid"]:
        if s in statuses:
            return s
    return ""

statuses = []

for row in (doc.documents or []):
    s = get_status(row.expiry_date)
    row.status = s
    if s:
        statuses.append(s)

doc.documents_status = worst_status(statuses)
